function estimateCard(e){
  const t=totals(e);
  return '<button class="est-result" onclick="zukaitEstimate.openEditor(\''+esc(e.id)+'\')"><b>'+esc(e.estimateNo)+'</b> · '+(e.status==='Saved'?'Saved':'Draft — not saved')+' · '+esc(e.date||'')+
    '<br>'+esc(e.customerName||'')+' · '+esc(e.makeModel||'')+(e.year?' · '+esc(e.year):'')+
    '<br><span class="small">'+esc(e.registration||'')+' · '+esc(e.type||'LS')+' · '+(e.vatEnabled?'VAT 5%':'NO VAT')+' · OMR '+money(t.total)+'</span></button>';
}
async function openHome(){
  if(!canUse())return alert('Supervisor or Manager access required.');
  await refreshEstimateRead();ensureStyle();ensureSharedEstimateUi();
  const recent=savedEstimates().slice().sort((a,b)=>(b.updatedAt||b.createdAt||0)-(a.updatedAt||a.createdAt||0)).slice(0,4);
  const html=nav('closeModal()')+'<div class="est-home"><div class="est-hero"><span class="est-eyebrow">ZUKAIT AUTO · SERVICE DESK</span><h3>Repair estimates</h3><p>Create a clear quote, review the costs and share it with your customer.</p></div><div class="est-grid2">'+
    '<button class="est-action" onclick="zukaitEstimate.newEstimate()"><b>➕ New Estimate</b><small>LS or Parts + Labour</small></button>'+
    '<button class="est-action" onclick="zukaitEstimate.openFind()"><b>🔎 Find Estimate</b><small>Estimate / Reg / Mobile / Claim</small></button>'+
    '<button class="est-action" onclick="zukaitEstimate.openDrafts()"><b>Draft estimates</b><small>Continue unsaved estimates</small></button>'+
    '<button class="est-action" onclick="zukaitEstimate.openRecent()"><b>🕘 Recent Estimates</b><small>Latest saved estimates</small></button>'+
    '<button class="est-action" onclick="zukaitEstimate.openReports()"><b>📊 Reports</b><small>Simple estimate totals</small></button>'+
    '</div><h4 class="est-recent-title">Recent estimates</h4>'+(recent.length?recent.map(estimateCard).join(''):'<div class="est-empty"><b>Your first estimate starts here</b><p>Create an estimate to keep customer details and repair costs together.</p></div>')+'</div>';
  openModal(html);
}
async function newEstimate(reception=null,requestKey=null,additionalRequestId=null){
  if(role()==='Receptionist'&&!reception)return alert('Open the Checklist to create its Estimate.');
  if(!canUse())return;
  ensureState();
  const existing=requestKey?findEstimate(requestKey):null;
  if(existing){
    if(reception&&(existing.receptionNo!==reception.rc_no||String(existing.receptionAdditionalRequestId||'')!==String(additionalRequestId||'')))throw Error('Saved estimate retry belongs to another reception request. Ask the Manager to reconcile it.');
    openEditor(existing.id);return existing.id;
  }
  if(!navigator.onLine||!window.zukaitCloud?.allocateEstimateNo){
    alert('Internet is required once to generate the official Zi-Qt estimate number.');return;
  }
  const clientKey=requestKey||uid();let a;
  try{a=await window.zukaitCloud.allocateEstimateNo(clientKey)}catch(e){alert('Unable to generate Estimate No. Please check connection and try again.');return}
  const u=currentUser()||{},e={
    id:clientKey,estimateNo:String(a?.estimate_no||''),sequenceNo:Number(a?.sequence_no||0),date:localDate(),type:'LS',vatEnabled:true,vatRate:.05,
    customerName:'',mobile:'',makeModel:'',year:'',registration:'',vin:'',claimNo:'',jobCard:'',
    customerSuppliedParts:'',showCustomerSuppliedParts:false,notes:'',
    lsRows:[{id:uid(),description:'',amount:0}],labourRows:[{id:uid(),description:'',amount:0}],partRows:[{id:uid(),description:'',qty:1,unitPrice:0}],
    lsSpareParts:0,misc:0,status:'Draft',createdAt:Date.now(),createdBy:u.id||'',updatedAt:Date.now(),updatedBy:u.id||'',revision:0
  };
  if(reception){
    const d=reception.details;
    Object.assign(e,{receptionNo:reception.rc_no,jobType:reception.job_type||'INSURANCE',insuranceCompany:reception.insurance_company,
      customerName:String(reception.job_type||'INSURANCE').toUpperCase()==='INSURANCE'?String(reception.insurance_company||'').trim():String(reception.job_type||'').toUpperCase()==='CREDIT'?String(d.company||d.company_name||d.customer||'').trim():String(d.customer||'').trim(),mobile:d.contact||'',makeModel:[d.make,d.model].filter(Boolean).join(' '),year:d.year||'',
      registration:d.registration||'',vin:d.vin||'',claimNo:d.claim||''});
    if(additionalRequestId)Object.assign(e,{jobCard:reception.job_card,receptionAdditionalRequestId:additionalRequestId});
  }
  if(!e.estimateNo)return alert('Estimate number allocation failed.');
  try{if(!reception)rememberEstimate(e)}catch(error){return alert('Could not retain this draft on the device. Estimate was not saved.');}
  state.estimates.unshift(e);if(reception){audit(e,'CREATE');saveState()}openEditor(e.id);return e.id;
}
let receptionEstimateBusy=false;
async function newFromReception(rcNo,additionalRequestId=null){
  if(!canUse()||receptionEstimateBusy)return;
  receptionEstimateBusy=true;
  try{
    if(role()==='Receptionist')await window.zukaitReceptionEstimate.prepare(rcNo);
    const response=await window.zukaitReception.call({operation:'GET',rc_no:rcNo});
    const r=response.record;
    if(r.outcome||(!additionalRequestId&&r.job_card)||(additionalRequestId&&(!r.job_card||response.additional?.can_prepare!==true||!response.additional.requests?.some(x=>x.id===additionalRequestId&&x.status==='DRAFT'))))throw Error('This reception case is not available for the requested estimate.');
    const actor=currentUser()?.id;
    if(!actor)throw Error('Please sign in.');
    const requestKey='zukait_reception_estimate_request_v1:'+JSON.stringify([actor,window.zukaitReception.endpoint||window.location?.origin||'',rcNo,additionalRequestId||'']);
    let clientKey=localStorage.getItem(requestKey);
    if(clientKey&&!/^(?:[a-f0-9-]{36}|est-\d+-[a-z0-9]+)$/i.test(clientKey))throw Error('Saved estimate retry could not be read. Keep device data and ask the Manager to reconcile it.');
    if(!clientKey){clientKey=uid();localStorage.setItem(requestKey,clientKey);if(localStorage.getItem(requestKey)!==clientKey)throw Error('This device could not save the estimate retry. No allocation was sent.');}
    const id=await newEstimate(r,clientKey,additionalRequestId);
    if(id&&localStorage.getItem(requestKey)===clientKey)localStorage.removeItem(requestKey);
    return id;
  }catch(e){alert(e.message||'Could not load reception information.');}
  finally{receptionEstimateBusy=false;}
}
